const {chromium}=require('./browser/node_modules/playwright');
(async()=>{const browser=await chromium.launch({headless:true});const page=await browser.newPage({viewport:{width:1400,height:1000}});const assets=[];page.on('response',r=>{if((r.headers()['content-type']||'').startsWith('image/'))assets.push({url:r.url(),type:r.headers()['content-type'],status:r.status()});});try{const response=await page.goto('https://chatgpt.com/s/m_6ab691ad087c81919ea2c882178b576d',{waitUntil:'domcontentloaded',timeout:30000});await page.waitForTimeout(6000);await page.screenshot({path:'work/food-share.png',fullPage:true});console.log(JSON.stringify({status:response.status(),title:await page.title(),assets,backgrounds:await page.locator('*').evaluateAll(nodes=>nodes.map(n=>getComputedStyle(n).backgroundImage).filter(s=>s!=='none')),images:await page.locator('img').evaluateAll(images=>images.map(i=>({src:i.currentSrc||i.src,alt:i.alt,width:i.naturalWidth,height:i.naturalHeight})))},null,2));}finally{await browser.close();}})();
